using FormSubmission.PublicPortal.Models; using System.Net.Http.Json; namespace FormSubmission.PublicPortal.Services; public class SubmissionApiService { private readonly HttpClient _http; public SubmissionApiService(IHttpClientFactory factory)=>_http=factory.CreateClient("Api"); public async Task<Guid?> CreateAsync(CreateSubmissionRequest r){var res=await _http.PostAsJsonAsync("api/submissions",r); if(!res.IsSuccessStatusCode)return null; var result=await res.Content.ReadFromJsonAsync<CreateSubmissionResponse>(); return result?.Id;} public async Task<SubmissionDto?> GetByIdAsync(Guid id)=>await _http.GetFromJsonAsync<SubmissionDto>($"api/submissions/{id}"); }